// Kill switch + janela + parametros. Tudo num no so para abortar cedo e barato.
// 15/08: passou a receber DUAS linhas de config (disparo + disparo_financeiro).
const linhas = $input.all().map(i => i.json).flat();
const pega = (k) => {
  const l = linhas.find(x => x && x.chave === k);
  return (l && l.valor) || {};
};
const cfg    = pega('disparo');
const cfgFin = pega('disparo_financeiro');

const ativo = cfg.ativo !== false;            // default ligado so se a chave existir
const modoTeste = cfg.modo_teste === true;
const numeroTeste = String(cfg.numero_teste || '');
const limiteDiario = Number(cfg.limite_diario != null ? cfg.limite_diario : 10);

if (modoTeste && !numeroTeste) throw new Error('modo_teste=true mas numero_teste nao configurado — abortando por seguranca');

// ===== LINHA FINANCEIRA — defaults DELIBERADAMENTE ASSIMETRICOS =====
// `ativo`: default DESLIGADO (=== true). Linha nova e opt-in explicito; chave
//   ausente ou ilegivel nao pode ligar disparo frio numa linha que nunca rodou.
// `modo_teste`: default LIGADO (!== false). Na duvida, manda para o numero de
//   teste, nunca para o lead.
const finAtivo      = cfgFin.ativo === true;
const finModoTeste  = cfgFin.modo_teste !== false;
const finNumeroTeste = String(cfgFin.numero_teste || numeroTeste || '');
const finCotaDia    = Number(cfgFin.proporcao_diaria != null ? cfgFin.proporcao_diaria : 2);

if (finAtivo && finModoTeste && !finNumeroTeste) {
  throw new Error('disparo_financeiro em modo_teste sem numero_teste — abortando por seguranca');
}

// Janela 8h–18h seg–sex (Sao Paulo = UTC-3, sem horario de verao)
const sp = new Date(Date.now() - 3 * 3600 * 1000);
const dia = sp.getUTCDay();
const hora = sp.getUTCHours();
const dentroJanela = dia >= 1 && dia <= 5 && hora >= 8 && hora < 18;

const prosseguir = ativo && dentroJanela;

return [{ json: {
  prosseguir,
  motivo_parada: !ativo ? 'kill_switch' : (!dentroJanela ? 'fora_da_janela' : null),
  modo_teste: modoTeste,
  numero_teste: numeroTeste,
  limite_diario: limiteDiario,
  fin_ativo: finAtivo,
  fin_modo_teste: finModoTeste,
  fin_numero_teste: finNumeroTeste,
  fin_cota_dia: finCotaDia,
  hoje_sp: sp.toISOString().slice(0, 10)
} }];

// Cota: conta interacoes msg1 de HOJE (fonte correta — corrige o bug do v3.1
// que contava por empresas.criado_em). msg1_teste nao entra (etapa diferente).
const ctx = $('Checar Kill Switch + Janela').first().json;
let regs = [];
try {
  regs = $input.all().map(i => i.json).flat().filter(j => j && j.id !== undefined);
} catch (e) { regs = []; }

const enviados = regs.length;
// Envio da linha financeira se identifica pelo roteiro usado.
const enviadosFin = regs.filter(r => String(r.roteiro_codigo || '').indexOf('financeiro') === 0).length;

// COTA GLOBAL: unica para as duas linhas. O numero de WhatsApp e o mesmo, e a
// LEI do warmup manda cota unica — duas contagens independentes seriam a D50
// multiplicada por dois.
const temCota = enviados < ctx.limite_diario;

// LINHA DESTA EXECUCAO. A financeira so entra se estiver ligada E ainda houver
// cota propria do dia. Fora isso, o comportamento e exatamente o de antes.
const podeFin = ctx.fin_ativo === true && enviadosFin < ctx.fin_cota_dia;
const linhaAlvo = podeFin ? 'financeiro' : 'presenca_digital';

return [{ json: {
  ...ctx,
  enviados_hoje: enviados,
  enviados_financeiro_hoje: enviadosFin,
  tem_cota: temCota,
  linha_alvo: linhaAlvo
} }];

// Valida se veio lead (fila pode estar vazia)
const itens = $input.all().map(i => i.json).flat().filter(l => l && l.id);
if (itens.length === 0) return [{ json: { __vazio: true } }];
const ctx = $('Calcular Cota').first().json;
return [{ json: { lead: itens[0], ctx } }];

// O claim é a proteção anti-duplicata: o PATCH só afeta a linha se ela AINDA
// estiver com status='fila'. Se outra execução chegou primeiro, a resposta vem
// vazia — e esta execução aborta sem enviar nada.
const resp = $input.all().map(i => i.json).flat().filter(r => r && r.id);
const base = $('Preparar Lead').first().json;
if (resp.length === 0) return [{ json: { __claim_falhou: true } }];
return [{ json: { lead: base.lead, ctx: base.ctx } }];

const base = $('Claim OK?').first().json;
const lead = base.lead;
const ctx = base.ctx;
let roteiros = [];
try { roteiros = $input.all().map(i => i.json).flat(); } catch (e) { roteiros = []; }

let roteiro = null;
if (ctx.linha_alvo === 'financeiro') {
  // 🔴 A LINHA E A CHAVE AQUI, nao o perfil_oferta.
  // Medido em 15/08: os leads da vw_fila_disparo_financeiro tem
  // perfil_oferta='redesign' — perfil de PRESENCA DIGITAL. Casar por
  // perfil_oferta mandaria a copy de redesign de site (PRIME30, R$ 599) para
  // um lead de controladoria. E financeiro_msg1 tem perfil_oferta='nao_aplica'
  // (sentinela da D36), valor que nenhum lead possui — entao ele NUNCA seria
  // escolhido pelo casamento antigo.
  roteiro = roteiros.find(r => r.linha === 'financeiro') || null;
} else {
  // DIGITAL: comportamento inalterado, com uma guarda a mais — nunca escolher
  // roteiro de outra linha, mesmo que a sentinela da D36 mude um dia.
  roteiro = roteiros.find(r => r.perfil_oferta === lead.perfil_oferta && r.linha !== 'financeiro') || null;
}

return [{ json: { lead, ctx, roteiro } }];

// Valida a mensagem e resolve o DESTINO.
// 15/08: passou a ser ciente de LINHA — modo_teste, numero de teste e copy de
// fallback sao proprios de cada linha.
const base = $('Juntar Lead + Roteiro').first().json;
const lead = base.lead;
const ctx = base.ctx;
const ehFin = ctx.linha_alvo === 'financeiro';

let texto = null;
try {
  texto = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
} catch (e) { texto = null; }

const PROIBIDAS = /\b(gr[aá]tis|promo[cç][aã]o|imperd[ií]vel|desconto|urgente|oportunidade [uú]nica)\b/i;
const TEM_LINK = /https?:\/\/|www\./i;
const valido = !!texto && !TEM_LINK.test(texto) && !PROIBIDAS.test(texto)
  && texto.length >= 60 && texto.length <= 700 && /\?/.test(texto);

// 🔴 O fallback digital fala de "presenca digital" — mandar isso para um lead de
// controladoria seria o mesmo vazamento que o casamento por perfil_oferta
// causava. Cada linha tem o seu.
const FALLBACK_DIGITAL = 'Oi, ' + (lead.nome_socio || '') + '! Tudo bem? Vi a ' + lead.nome_exibicao + ' aqui em ' + lead.municipio + ' e reparei em algumas coisas na presenca digital de voces que podem estar deixando clientes pelo caminho. Posso te mostrar rapidinho o que encontrei?';
// Financeiro: gancho + oferta do Raio-X + pedido de permissao, SEM LINK
// (o link so vai depois do sim — regra da msg1 financeira).
const FALLBACK_FINANCEIRO = 'Oi, ' + (lead.nome_socio || '') + '! Tudo bem? Trabalho com controle financeiro para pequenos negocios e queria te oferecer um Raio-X do caixa da ' + lead.nome_exibicao + ': sao 10 perguntas rapidas e no fim voce recebe a leitura de onde o dinheiro pode estar vazando. Posso te explicar como funciona?';

const FALLBACK = (ehFin ? FALLBACK_FINANCEIRO : FALLBACK_DIGITAL).replace(/\s+/g, ' ').trim();

const mensagem = valido ? texto : FALLBACK;

// Modo teste e numero de teste sao POR LINHA.
const modoTeste  = ehFin ? ctx.fin_modo_teste : ctx.modo_teste;
const numeroTeste = ehFin ? ctx.fin_numero_teste : ctx.numero_teste;
const destino = modoTeste ? numeroTeste : String(lead.whatsapp || '');
if (!destino) throw new Error('Lead sem WhatsApp — abortando (lead ' + lead.slug + ' fica em status abordando para revisao)');

// Delay humano aleatorio: 60s a 40min antes do envio
const delaySegundos = 60 + Math.floor(Math.random() * 2340);

return [{ json: {
  lead, ctx, mensagem,
  copy_fallback: !valido,
  destino,
  linha_alvo: ctx.linha_alvo,
  roteiro_codigo: (base.roteiro && base.roteiro.codigo) || null,
  etapa: modoTeste ? 'msg1_teste' : 'msg1',
  delay_segundos: delaySegundos
} }];

// Interpreta o resultado do envio. NUNCA faz retry — falha vai para o branch de alerta.
const prep = $('Validar + Resolver Destino').first().json;
const resp = $input.first().json || {};
const evolutionId = resp?.key?.id || null;
const enviou = !!evolutionId;
return [{ json: { ...prep, enviou, evolution_id: evolutionId, resposta_envio: enviou ? null : JSON.stringify(resp).slice(0, 400) } }];

